package main

const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shiraz Phone</title>
<style>
:root{font-family:system-ui,sans-serif;color:#e8e8e8;background:#000;color-scheme:dark}
*{box-sizing:border-box}html{background:#000}body{margin:0;min-height:100vh;background:radial-gradient(ellipse 52% 42% at 70% 42%,#d8e6ff0c,transparent 75%),#000;line-height:1.7;-webkit-font-smoothing:antialiased}
button,input{font:inherit}button:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid #fff;outline-offset:3px}
main{width:100%;min-height:100vh}
.status{display:inline-block;margin:18px 0 0;font-size:11px;letter-spacing:.05em;text-transform:uppercase;color:#777}.status:before{content:'';display:inline-block;width:6px;height:6px;background:#666;border-radius:50%;margin-right:9px;vertical-align:2px}.status.online:before{background:#d8e6ff;box-shadow:0 0 8px #d8e6ff80}
.layout{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));align-items:start;min-height:100vh}.phone-stage{position:sticky;top:0;height:100vh;display:grid;place-items:center;padding:24px;border-right:1px solid #242424}.workspace{min-height:100vh;display:flex;flex-direction:column;justify-content:center;padding:clamp(32px,5vw,72px) clamp(28px,6vw,96px)}
.phone{width:min(100%,390px,calc(52vh - 50px));margin:auto;padding:10px;border:1px solid #4c4c4c;border-radius:43px;background:#080808;box-shadow:0 0 0 4px #151515,0 26px 80px #000;position:relative}.earpiece{height:16px;width:76px;border-radius:0 0 12px 12px;background:#080808;position:absolute;top:0;left:50%;transform:translateX(-50%);z-index:2}.screen{position:relative;aspect-ratio:9/16;overflow:hidden;background:#0c0c0c;border-radius:34px;touch-action:none;user-select:none}.screen video{display:block;width:100%;height:100%;object-fit:fill;visibility:hidden}.screen.ready video{visibility:visible}.empty{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:30px;color:#777;font-size:13px}.empty .icon{font-size:32px;font-weight:200;color:#bdbdbd;margin-bottom:20px}.empty strong{color:#f2f2f2;font-size:18px;font-weight:450;margin-bottom:7px}.screen.ready .empty{display:none}.nav{height:40px;display:flex;align-items:center;justify-content:space-around}.nav button{border:0;background:none;color:#aaa;font-size:23px;cursor:pointer;width:52px;height:36px;line-height:1}.nav button:hover{color:#fff}
.panel{padding:14px 0}.eyebrow{font-size:10px;letter-spacing:1.3px;text-transform:uppercase;color:#777;margin:0 0 30px}.panel h2{font-size:clamp(32px,4.2vw,48px);font-weight:450;letter-spacing:-1.7px;line-height:1.16;color:#f2f2f2;margin:0}.muted{font-size:15px;color:#999;line-height:1.8;margin:22px 0 0;max-width:470px}.card{background:#080808;border:1px solid #242424;border-radius:8px;padding:24px;margin-top:30px}.card label{display:block;font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#aaa;margin-bottom:15px}.card input[type=file],.card input[type=text]{display:block;width:100%;border:1px solid #3a3a3a;border-radius:4px;background:#101010;color:#d2d2d2;padding:12px;font-size:13px}.card input[type=file]::file-selector-button{color:#eee;background:#242424;border:1px solid #404040;border-radius:3px;padding:7px 11px;margin-right:12px;cursor:pointer}.primary{display:inline-block;background:#f2f2f2;border:1px solid #f2f2f2;border-radius:4px;color:#080808;font-size:12px;font-weight:600;letter-spacing:.02em;padding:11px 17px;margin-top:18px;cursor:pointer;transition:background .18s,border-color .18s}.primary:hover{background:#c8d0da;border-color:#c8d0da}.primary:disabled{opacity:.45;cursor:wait}.note{font-size:11px;color:#777;margin:16px 0 0}.logs{margin-top:24px;border-top:1px solid #242424;padding-top:16px}.logs summary{cursor:pointer;color:#999;font-size:12px}.logs pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:290px;overflow:auto;background:#080808;border:1px solid #242424;border-radius:5px;padding:14px;color:#aaa;font-size:11px;line-height:1.5}
footer{margin-top:64px;border-top:1px solid #242424;padding:18px 0;font-size:11px;color:#606060;display:flex;justify-content:space-between;gap:20px}footer a{color:#aaa;text-decoration:none}footer a:hover{color:#fff}
@media(max-width:760px){.layout{grid-template-columns:1fr}.phone-stage{position:relative;height:auto;min-height:0;padding:36px 24px;border-right:0;border-bottom:1px solid #242424}.workspace{min-height:0;padding:36px 24px}.phone{width:min(100%,345px)}.panel{padding:0}.eyebrow{margin-bottom:18px}.panel h2{font-size:36px}.card{margin-top:24px}footer{margin-top:44px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style></head><body><main><div class="layout"><div class="phone-stage"><div class="phone"><div id="screen" class="screen"><div class="earpiece"></div><video id="frame" autoplay playsinline muted aria-label="Live Android app screen"></video><div class="empty"><div class="icon">◇</div><strong>Your app appears here</strong><span>Upload an APK to start the phone.</span></div></div><div class="nav"><button id="back" title="Back" aria-label="Back">‹</button><button id="stop" title="Stop app" aria-label="Stop app">○</button><button id="refresh" title="Refresh screen" aria-label="Refresh screen">↻</button></div></div></div><div class="workspace"><section class="panel"><p class="eyebrow">03 / ANDROID · TRANSLATION LAYER</p><h2>Android apps.<br>Linux, your way.</h2><span id="status" class="status" role="status" aria-live="polite">Connecting</span><p class="muted">Choose an APK. Shiraz runs it on this Linux server and shows its screen here. Touch or drag the phone screen. Hover over it to send keyboard input to the app.</p><form id="form" class="card"><label for="apk">APK file</label><input id="apk" name="apk" type="file" accept=".apk,application/vnd.android.package-archive" required><button class="primary" id="send" disabled>Upload and run</button><p class="note">One app at a time · Up to 256 MiB · 30 minute session</p></form><div class="logs"><details><summary>Run log</summary><pre id="log"></pre></details></div></section><footer><span>SpectreOSS / Shiraz · Experimental</span><a href="https://spectre-oss.github.io/">Back to SpectreOSS ↗</a></footer></div></div></main>
<script>
const status=document.querySelector('#status'),screen=document.querySelector('#screen'),frame=document.querySelector('#frame'),send=document.querySelector('#send'),log=document.querySelector('#log');
let peer,channel,connected=false,hover=false,drag=false,reconnecting=false,videoReady=false,appActive=false,lastMove=0;const held=new Set();
function setStatus(message,online){status.textContent=message;status.classList.toggle('online',online)}
function input(action,x=0,y=0,key='',text=''){if(channel?.readyState==='open')channel.send(JSON.stringify({action,x,y,key,text}))}
function releaseKeys(){for(const key of held)input('keyup',0,0,key);held.clear()}
function retry(){if(reconnecting)return;reconnecting=true;connected=false;send.disabled=true;releaseKeys();setStatus('Reconnecting',false);peer?.close();setTimeout(()=>{reconnecting=false;connect()},1600)}
async function connect(){try{
 peer=new RTCPeerConnection({iceServers:[]});channel=peer.createDataChannel('control');peer.addTransceiver('video',{direction:'recvonly'});
 channel.onopen=()=>{connected=true;send.disabled=false;setStatus('Connected',true)};
 channel.onmessage=e=>{const msg=JSON.parse(e.data);if(msg.type==='status'){setStatus(msg.message,true);appActive=/running|Starting|accepted/i.test(msg.message);screen.classList.toggle('ready',appActive&&videoReady)}else{log.textContent+=msg.message+'\n';log.scrollTop=log.scrollHeight;if(msg.type==='error'){appActive=false;screen.classList.remove('ready');setStatus('Run failed',false)}}};
 const currentPeer=peer;currentPeer.ontrack=e=>{if(currentPeer!==peer)return;frame.srcObject=new MediaStream([e.track]);frame.play().catch(()=>{})};frame.onplaying=()=>{videoReady=true;screen.classList.toggle('ready',appActive)};
 currentPeer.onconnectionstatechange=()=>{if(currentPeer===peer&&['failed','closed','disconnected'].includes(currentPeer.connectionState))retry()};
 const offer=await peer.createOffer();await peer.setLocalDescription(offer);
 if(peer.iceGatheringState!=='complete')await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('ICE gathering timed out')),15000);peer.addEventListener('icegatheringstatechange',()=>{if(peer.iceGatheringState==='complete'){clearTimeout(timeout);resolve()}},{once:false})});
 const response=await fetch('/webrtc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(peer.localDescription)});
 if(!response.ok)throw Error(await response.text());await peer.setRemoteDescription(await response.json());
 }catch(error){log.textContent+=error.message+'\n';retry()}}
 connect();function point(e){const r=screen.getBoundingClientRect();return{x:Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}}
 screen.addEventListener('pointerenter',()=>{hover=true});screen.addEventListener('pointerleave',()=>{hover=false;releaseKeys()});window.addEventListener('blur',()=>{hover=false;releaseKeys()});
 window.addEventListener('keydown',e=>{if(!hover||!connected)return;e.preventDefault();if(!held.has(e.code)){held.add(e.code);input('keydown',0,0,e.code)}if(e.key.length===1&&!e.ctrlKey&&!e.metaKey&&!e.altKey)input('text',0,0,'',e.key)});
 window.addEventListener('keyup',e=>{if(!held.has(e.code))return;e.preventDefault();held.delete(e.code);input('keyup',0,0,e.code)});
 const controls=document.createElement('div');controls.className='card';controls.innerHTML='<label for="typing">Type into the app</label><input id="typing" type="text" maxlength="30" placeholder="Text for the focused field"><button id="type-send" class="primary" type="button">Send text</button><button id="enter" class="primary" type="button" style="margin-left:8px;background:#101010;color:#eee;border-color:#454545">Enter</button>';document.querySelector('.panel').insertBefore(controls,document.querySelector('.logs'));document.querySelector('#type-send').onclick=()=>{const field=document.querySelector('#typing');if(field.value&&connected){input('text',0,0,'',field.value);field.value=''}};document.querySelector('#enter').onclick=()=>input('enter');
 screen.addEventListener('pointerdown',e=>{if(!screen.classList.contains('ready'))return;drag=true;screen.setPointerCapture(e.pointerId);const p=point(e);input('fingerdown',p.x,p.y)});screen.addEventListener('pointermove',e=>{if(drag&&performance.now()-lastMove>50){lastMove=performance.now();const p=point(e);input('fingermove',p.x,p.y)}});function end(e){if(drag){drag=false;const p=point(e);input('fingerup',p.x,p.y)}}screen.addEventListener('pointerup',end);screen.addEventListener('pointercancel',end);document.querySelector('#back').onclick=()=>input('back');document.querySelector('#stop').onclick=()=>input('stop');document.querySelector('#refresh').onclick=()=>{frame.play().catch(()=>{})};
 document.querySelector('#form').onsubmit=async e=>{e.preventDefault();send.disabled=true;log.textContent='';setStatus('Uploading',true);try{const response=await fetch('/upload',{method:'POST',body:new FormData(e.target)});if(!response.ok)throw Error((await response.text()).trim());appActive=true;screen.classList.toggle('ready',videoReady);setStatus('Starting',true)}catch(error){setStatus('Upload failed',false);log.textContent=error.message}finally{send.disabled=!connected}};
</script></body></html>`
